# Conservative approach: only fill 7s that are between 8s (horizontally) in the same row
# This matches "between" pattern from demo

def horizontal_between(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(1, w-1):
            if result[r][c] == 7:
                # Check if this cell is between 8s horizontally
                if result[r][c-1] == 8 and result[r][c+1] == 8:
                    result[r][c] = 3

    return result

