# Let me try: just fill horizontally between 8s
def fill_horizontal_between(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        eight_cols = [c for c in range(w) if result[r][c] == 8]
        pairs = []
        for i in range(len(eight_cols) - 1):
            pairs.append((eight_cols[i], eight_cols[i+1]))

        for c1, c2 in pairs:
            for c in range(c1 + 1, c2):
                if result[r][c] == 7:
                    result[r][c] = 3

    return result

result_h = fill_horizontal_between(test_input)
print("Horizontal gaps only:")
for row in result_h:
